-- Ejecutar después de 0038_activos.sql. PRUEBAS OK revierte los datos de prueba.
do $$
declare admin_id uuid;corp_id uuid;s uuid;s2 uuid;p uuid;i uuid;x uuid;y uuid;m uuid;d jsonb;md jsonb;hoy date:=(now() at time zone 'America/Mexico_City')::date;
begin
 select id into admin_id from public.perfiles where activo and rol::text='admin' limit 1;
 select id into corp_id from public.perfiles where activo and rol::text='corporativo' limit 1;
 select id,sucursal_id into p,s from public.apertura_proyectos limit 1;
 select id into s2 from public.sucursales where id<>s limit 1;
 if admin_id is null or corp_id is null or p is null or s2 is null then raise exception 'FALTAN DATOS: admin, corporativo, apertura y dos sucursales.';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',admin_id,'role','authenticated')::text,true);
 d:=jsonb_build_object('sucursal_id',s2,'nombre','Activo existente de prueba','categoria','cocina','estado','en_uso');
 begin perform public.guardar_activo(null,0,d||'{"costo":"-1"}'::jsonb);raise exception 'FALLÓ: costo negativo';exception when check_violation then null;end;
 x:=public.guardar_activo(null,0,d);
 if not exists(select 1 from public.activos where id=x and costo is null and revision=1) then raise exception 'FALLÓ: alta sin costo conocido';end if;
 perform public.valuar_activo(x,hoy,10000,'Estimación por condición física','Fotos de prueba');
 perform public.valuar_activo(x,hoy,9000,'Corrección con cotización de reposición','Cotización de prueba');
 if (select count(*) from public.activo_valuaciones where activo_id=x)<>2 then raise exception 'FALLÓ: historial de valuaciones';end if;
 if (select costo from public.activos where id=x) is not null then raise exception 'FALLÓ: valuación altera costo';end if;
 begin perform public.valuar_activo(x,hoy,-1,'Negativa de prueba','');raise exception 'FALLÓ: valor negativo';exception when check_violation then null;end;
 begin perform public.valuar_activo(x,hoy+1,10,'Fecha futura de prueba','');raise exception 'FALLÓ: valuación futura';exception when others then if sqlerrm<>'Fecha o evidencia inválida.' then raise;end if;end;
 begin perform public.guardar_activo(x,0,d);raise exception 'FALLÓ: edición simultánea';exception when others then if sqlerrm<>'El activo cambió. Recarga antes de guardar.' then raise;end if;end;
 begin perform public.guardar_activo(x,1,d||'{"codigo":1}'::jsonb);raise exception 'FALLÓ: código modificable';exception when others then if sqlerrm<>'Campos inválidos.' then raise;end if;end;
 begin perform public.guardar_activo(x,1,d||'{"estado":"baja"}'::jsonb);raise exception 'FALLÓ: baja sin motivo';exception when others then if sqlerrm<>'Registra el motivo y evidencia de la baja.' then raise;end if;end;
 perform public.guardar_activo(x,1,d||jsonb_build_object('sucursal_id',s,'ubicacion','Cocina'));
 if not exists(select 1 from public.activo_historial where activo_id=x and evento='Traslado' and anterior->>'sucursal_id'=s2::text and nuevo->>'sucursal_id'=s::text) then raise exception 'FALLÓ: traslado sin historial';end if;
 i:=public.agregar_apertura_item(p,'equipo','P4','Dos equipos de prueba');
 d:=jsonb_build_object('sucursal_id',s,'nombre','Unidad de apertura','categoria','refrigeracion','estado','recibido','apertura_item_id',i);
 begin perform public.guardar_activo(null,0,d);raise exception 'FALLÓ: alta antes de recepción';exception when others then if sqlerrm<>'Primero registra la recepción del equipo en Aperturas.' then raise;end if;end;
 perform public.actualizar_apertura_item(i,1,'{"estado":"recibido","cantidad":"2","recibido":"2","evidencia":"Recepción de prueba"}');
 y:=public.guardar_activo(null,0,d);
 perform public.guardar_activo(null,0,d);
 begin perform public.guardar_activo(null,0,d);raise exception 'FALLÓ: unidades duplicadas';exception when others then if sqlerrm<>'Ya se registraron las unidades recibidas de este equipo.' then raise;end if;end;
 begin perform public.guardar_activo(y,1,d||'{"apertura_item_id":""}'::jsonb);raise exception 'FALLÓ: borra origen';exception when others then if sqlerrm<>'El origen del activo se conserva.' then raise;end if;end;
 begin perform public.guardar_activo(null,0,d||jsonb_build_object('sucursal_id',s2));raise exception 'FALLÓ: origen otra sucursal';exception when others then if sqlerrm<>'La sucursal debe corresponder a la apertura.' then raise;end if;end;
 begin perform public.guardar_activo(x,2,jsonb_build_object('sucursal_id',s,'nombre','Prueba','categoria','otros','estado','en_uso','factura_id',gen_random_uuid()));raise exception 'FALLÓ: factura ajena';exception when others then if sqlerrm<>'La factura debe corresponder a la sucursal.' then raise;end if;end;
 md:=jsonb_build_object('tipo','preventivo','tarea','Limpieza y revisión','programado',hoy+7,'estado','pendiente');
 perform public.mantener_activo(x,null,0,md);
 select id into m from public.activo_mantenimientos where activo_id=x;
 begin perform public.mantener_activo(x,m,1,md||'{"estado":"completado"}');raise exception 'FALLÓ: cierre sin resultado';exception when check_violation then null;end;
 begin perform public.mantener_activo(x,m,1,md||jsonb_build_object('estado','completado','realizado',hoy,'costo','0'));raise exception 'FALLÓ: cierre sin evidencia';exception when check_violation then null;end;
 begin perform public.mantener_activo(x,m,1,md||'{"estado":"anulado"}');raise exception 'FALLÓ: anulación sin motivo';exception when check_violation then null;end;
 perform public.mantener_activo(x,m,1,md||jsonb_build_object('estado','completado','realizado',hoy,'costo','0','evidencia','Servicio sin costo de prueba'));
 begin perform public.mantener_activo(x,m,2,md);raise exception 'FALLÓ: reabre servicio';exception when others then if sqlerrm<>'El servicio ya se cerró. Conserva su historial y registra otro.' then raise;end if;end;
 perform public.mantener_activo(x,null,0,md);
 if (select count(*) from public.activo_mantenimientos where activo_id=x)<>2 then raise exception 'FALLÓ: siguiente mantenimiento';end if;
 if (select count(*) from public.activo_historial where activo_id=x)<7 then raise exception 'FALLÓ: historial incompleto';end if;
 set local role authenticated;
 perform set_config('request.jwt.claims',json_build_object('sub',corp_id,'role','authenticated')::text,true);
 if not exists(select 1 from public.activos where id=x) or not exists(select 1 from public.activo_valuaciones where activo_id=x) or not exists(select 1 from public.activo_mantenimientos where activo_id=x) then raise exception 'FALLÓ: corporativo no consulta';end if;
 begin perform public.guardar_activo(null,0,d);raise exception 'FALLÓ: corporativo crea';exception when others then if sqlerrm<>'Solo administración puede gestionar activos.' then raise;end if;end;
 begin perform public.valuar_activo(x,hoy,1,'No autorizado','');raise exception 'FALLÓ: corporativo valúa';exception when others then if sqlerrm<>'Solo administración puede gestionar activos.' then raise;end if;end;
 begin perform public.mantener_activo(x,null,0,md);raise exception 'FALLÓ: corporativo mantiene';exception when others then if sqlerrm<>'Solo administración puede gestionar activos.' then raise;end if;end;
 begin update public.activos set costo=1 where id=x;raise exception 'FALLÓ: escritura directa';exception when insufficient_privilege then null;end;
 if has_table_privilege('authenticated','public.activo_valuaciones','INSERT') or has_table_privilege('authenticated','public.activo_mantenimientos','UPDATE') or has_table_privilege('authenticated','public.activo_historial','DELETE') then raise exception 'FALLÓ: permisos';end if;
 perform set_config('request.jwt.claims','{"role":"authenticated"}',true);
 if exists(select 1 from public.activos where id=x) then raise exception 'FALLÓ: consulta sin perfil';end if;
 raise exception 'PRUEBAS OK — inventario existente · valuaciones con historial · conserva costo · traslado · unidades recibidas sin duplicados · conserva origen · factura de sucursal · mantenimiento y evidencia · cierre único · siguiente servicio · evita sobrescritura · corporativo consulta · sin escritura directa';
end $$;
